public class ThumbCacheUtil {

    /**
     * Maps a file key to a thumbnail hash.
     * Used to know which thumbnail belongs to which file.
     */
    private static final Map<String, String> FILE_THUMB_INDEX = new ConcurrentHashMap<>();

    /**
     * Maps thumbnail hash to image bytes.
     * Duplicate thumbnails are naturally avoided because identical content
     * generates the same hash key.
     */
    private static final Map<String, byte[]> THUMB_CACHE = new ConcurrentHashMap<>();

    /**
     * Caches the received thumbnail image.
     * If the same thumbnail image content already exists, it will not be stored again.
     *
     * @param fileInfo the information about the file
     * @param inputStream the input stream containing the thumbnail image data
     * @throws IOException if an I/O error occurs
     */
    public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
        if (fileInfo == null || inputStream == null) {
            return;
        }

        boolean isContain = false;

        try {
            byte[] thumbBytes = readAllBytes(inputStream);
            if (thumbBytes.length == 0) {
                return;
            }

            // Build a unique hash for image content
            String thumbHash = sha256(thumbBytes);

            // Check whether this thumbnail content already exists
            isContain = THUMB_CACHE.containsKey(thumbHash);

            // Cache image data only if not already present
            if (!isContain) {
                THUMB_CACHE.put(thumbHash, thumbBytes);
            }

            // Associate current file with the thumbnail hash
            String fileKey = buildFileKey(fileInfo);
            FILE_THUMB_INDEX.put(fileKey, thumbHash);

        } catch (IOException e) {
            throw e;
        } catch (Exception e) {
            throw new IOException("Failed to cache thumbnail", e);
        }
    }

    private static String buildFileKey(BaseFileInfo fileInfo) {
        return fileInfo.getName() + "_" + fileInfo.getSize() + "_" + fileInfo.getType();
    }

    private static byte[] readAllBytes(InputStream inputStream) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        byte[] buffer = new byte[4096];
        int len;
        while ((len = inputStream.read(buffer)) != -1) {
            bos.write(buffer, 0, len);
        }
        return bos.toByteArray();
    }

    private static String sha256(byte[] data) throws IOException {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(data);
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("SHA-256 algorithm not available", e);
        }
    }

    // Optional helper methods

    public static byte[] getThumb(BaseFileInfo fileInfo) {
        String fileKey = buildFileKey(fileInfo);
        String thumbHash = FILE_THUMB_INDEX.get(fileKey);
        return thumbHash == null ? null : THUMB_CACHE.get(thumbHash);
    }

    public static boolean containsThumb(BaseFileInfo fileInfo) {
        String fileKey = buildFileKey(fileInfo);
        return FILE_THUMB_INDEX.containsKey(fileKey);
    }
}
```

### How it works
- The thumbnail stream is fully read into a byte array.
- A SHA-256 hash is generated from the thumbnail bytes.
- That hash is used as the cache key for the image content.
- If the hash already exists in `THUMB_CACHE`, the image is a duplicate and is not stored again.
- The file is still linked to the existing thumbnail via `FILE_THUMB_INDEX`.

### Why this avoids duplicates
Two identical thumbnail images produce the same hash, so only one copy of the byte data is stored.

