function prod_signs($arr) {
    // Helper function to check if a number is prime
    function is_prime($n) {
        // Numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }

        // Check divisibility from 2 up to square root of n
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false;
            }
        }

        return true;
    }

