    $primes = [];

    // Find values whose absolute value is prime
    foreach ($uniqueValues as $value) {
        if (is_prime(abs($value))) {
            $primes[] = $value;
        }
    }

    // If there are no prime-related values, return null
    if (empty($primes)) {
        return null;
    }

    $sum = 0;

    // For each prime value:
    // - if it appears an even number of times in the original array, add it
    // - if it appears an odd number of times, subtract it
    foreach ($primes as $prime) {
        $count = 0;

        // Count how many times this prime appears in the original array
        foreach ($arr as $item) {
            if ($item == $prime) {
                $count++;
            }
        }

        // Add or subtract depending on whether the count is even or odd
        if ($count % 2 == 0) {
            $sum += $prime;
        } else {
            $sum -= $prime;
        }
    }

    return $sum;
}

