```rust
// This is the GridMaster's API interface.
// You should not implement it, or speculate about its implementation.
#[allow(dead_code)]
trait GridMaster {
    fn can_move(&self, direction: char) -> bool;
    fn move_(&mut self, direction: char) -> i32;
    fn is_target(&self) -> bool;
}

use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

struct Solution;

impl Solution {
    pub fn find_shortest_path(master: &mut impl GridMaster) -> i32 {
        let dirs = [('U', -1, 0), ('D', 1, 0), ('L', 0, -1), ('R', 0, 1)];
        let opposite = |d: char| -> char {
            match d {
                'U' => 'D',
                'D' => 'U',
                'L' => 'R',
                'R' => 'L',
                _ => unreachable!(),
            }
        };

        let mut costs: HashMap<(i32, i32), i32> = HashMap::new();
        let mut target: Option<(i32, i32)> = None;

        costs.insert((0, 0), 0);

        fn dfs(
            master: &mut impl GridMaster,
            x: i32,
            y: i32,
            costs: &mut HashMap<(i32, i32), i32>,
            target: &mut Option<(i32, i32)>,
            dirs: &[(char, i32, i32); 4],
        ) {
            if master.is_target() {
                *target = Some((x, y));
            }

            for &(dir, dx, dy) in dirs.iter() {
                let nx = x + dx;
                let ny = y + dy;

                if costs.contains_key(&(nx, ny)) {
                    continue;
                }

                if !master.can_move(dir) {
                    continue;
                }

                let c = master.move_(dir);
                costs.insert((nx, ny), c);

                dfs(master, nx, ny, costs, target, dirs);

                let back = match dir {
                    'U' => 'D',
                    'D' => 'U',
                    'L' => 'R',
                    'R' => 'L',
                    _ => unreachable!(),
                };
                master.move_(back);
            }
        }

        dfs(master, 0, 0, &mut costs, &mut target, &dirs);

        let target = match target {
            Some(t) => t,
            None => return -1,
        };

        let mut dist: HashMap<(i32, i32), i32> = HashMap::new();
        let mut pq: BinaryHeap<(Reverse<i32>, i32, i32)> = BinaryHeap::new();

        dist.insert((0, 0), 0);
        pq.push((Reverse(0), 0, 0));

        while let Some((Reverse(d), x, y)) = pq.pop() {
            if (x, y) == target {
                return d;
            }

            if let Some(&best) = dist.get(&(x, y)) {
                if d > best {
                    continue;
                }
            }

            for &(_, dx, dy) in dirs.iter() {
                let nx = x + dx;
                let ny = y + dy;

                if let Some(&move_cost) = costs.get(&(nx, ny)) {
                    let nd = d + move_cost;
                    let prev = dist.get(&(nx, ny)).copied().unwrap_or(i32::MAX);
                    if nd < prev {
                        dist.insert((nx, ny), nd);
                        pq.push((Reverse(nd), nx, ny));
                    }
                }
            }
        }

        -1
    }
}
