    if (!grid) return "";

    int cols = grid->GetNumberCols();
    for (int col = 0; col < cols; ++col)
    {
        if (grid->GetColLabelValue(col) == label)
        {
            if (row >= 0 && row < grid->GetNumberRows())
                return grid->GetCellValue(row, col);
            break;
        }
    }

    return ""; // not found or invalid row
}
