    if s[i] = '0' then
    begin
      { Value 0 is represented by the single character "0".
        This is always the shortest possible for value 0. }
      if best[0].L = -1 then
      begin
        best[0].L := i - 1;
        best[0].R := i - 1;
      end;
      Continue;
    end;

    val := 0;
    for j := i to Min(n, i + maxLen - 1) do
    begin
      val := (val shl 1) + Ord(s[j] = '1');

      if best[val].L = -1 then
      begin
        best[val].L := i - 1;
        best[val].R := j - 1;
      end;
    end;
  end;

  q := Length(queries);
  SetLength(Result, q);

  for i := 0 to q - 1 do
  begin
    target := queries[i][0] xor queries[i][1];
    SetLength(Result[i], 2);

    if (target >= 0) and (target < Length(best)) and (best[target].L <> -1) then
    begin
      Result[i][0] := best[target].L;
      Result[i][1] := best[target].R;
    end
    else
    begin
      Result[i][0] := -1;
      Result[i][1] := -1;
    end;
  end;
end;

end.
```

### Explanation

For each query:

- We need a substring whose decimal value is `val`
- Such that `val xor first = second`
- Therefore:
  `val = first xor second`

So each query becomes:

- find the shortest substring in `s` with decimal value `target = first xor second`

### Key optimization

A substring longer than 30 bits is unnecessary because:

- `firsti, secondi <= 10^9`
- so `target <= 2^30 - 1`

Thus we only enumerate substrings of length at most `30`.

### Algorithm

1. Precompute every substring value of length at most `30`
2. Store the first occurrence of each value
   - because we scan left to right
   - and shorter substrings are found first for each start
3. For each query:
   - compute `target = first xor second`
   - return stored interval or `[-1, -1]`

### Complexity

- Preprocessing: `O(n * 30)`
- Each query: `O(1)`
- Total: `O(n * 30 + q)`

This works efficiently for the given constraints.

```javascript
function sortBooks(books) {
  return books
    .map((title, index) => ({ title, index })) // keep original index for stable order
    .sort((a, b) => {
      const firstA = a.title[0];
      const firstB = b.title[0];

      const isDigitA = firstA >= '0' && firstA <= '9';
      const isDigitB = firstB >= '0' && firstB <= '9';

      // Numbers come before letters
      if (isDigitA && !isDigitB) return -1;
      if (!isDigitA && isDigitB) return 1;

      // Sort by starting character, case-sensitive
      if (firstA !== firstB) {
        return firstA.charCodeAt(0) - firstB.charCodeAt(0);
      }

      // Same starting letter: sort by length descending
      if (a.title.length !== b.title.length) {
        return b.title.length - a.title.length;
      }

      // Same starting letter and length: sort by full ASCII value descending
      if (a.title !== b.title) {
        for (let i = 0; i < a.title.length; i++) {
          const diff = b.title.charCodeAt(i) - a.title.charCodeAt(i);
          if (diff !== 0) return diff;
        }
      }

      // Keep original order if completely tied
      return a.index - b.index;
    })
    .map(book => book.title);
}

